import assert from 'node:assert/strict';
import path from 'node:path';
import {readFile,stat} from 'node:fs/promises';
import {sha256} from '../../host/instance-runtime/bytes.mjs';
import {productionBindingReasons} from '../../host/instance-runtime/shot-production-model.mjs';
import {preserveMaterialProductionProjection} from '../../host/instance-runtime/material-production-preservation.mjs';
import {legacyObjects} from '../material-production-fixture.mjs';
import {apiFixture,pngs} from './material-native-revision-api.mjs';

export async function failedRemakeApiCase(t,{referenceInput=false,verifyNativeProof=null}={}){
 const f=await apiFixture(t),legacy=legacyObjects(await f.repo.readView());
 const first=await f.provision(await f.workspace(),'First fixed local PNG fixture; no model invocation.');
 const run1=await f.beginRun(first),v1=await f.register(first,run1,pngs[0]);
 await f.review(first,v1,'APPROVE_AND_RELEASE');
 const inputBindings=referenceInput?[{familyId:first.result.familyId,versionId:v1.versionId,sha256:v1.sha256}]:[];
 const second=await f.provision(await f.workspace(),'Second fixed attempt; simulated failure without output.',{expectedMode:'REVISION',inputBindings});
 assert.equal(second.plan.expectedOutput.plannedVersionLabel,'V002');
 assert.equal(second.recipe.parentVersionId,v1.versionId);
 assert.equal(second.recipe.parentVersionSha256,v1.sha256);
 const familyId=first.result.familyId,missingVersionId=familyId+'@V002';
 const boundV1={familyId,versionId:v1.versionId,sha256:v1.sha256};
 const assertAdoptedV1=async()=>{
  const data=await f.store.reviewData(),state=(await f.store.operationalSnapshot()).stateProjection;
  assert.equal(state.assetFamiliesById[familyId].currentVersionId,v1.versionId);
  assert.equal(state.assetFamiliesById[familyId].currentExpectedOutputId,null);
  assert.equal(state.assetVersionsById[v1.versionId].canFlowDownstream,true);
  assert.deepEqual(productionBindingReasons(data.productionModel,state,boundV1),[]);
  assert.ok((await f.workspace()).availableInputs.some(b=>b.familyId===familyId&&b.versionId===v1.versionId&&b.sha256===v1.sha256));
 };
 const assertNoV2Output=async()=>{
  const view=await f.repo.readView();
  assert.equal((view.eventsByKind['asset-version']||[]).some(e=>e.versionId===missingVersionId||e.expectedOutputId===second.recipe.output.expectedOutputRef),false);
  assert.equal((view.snapshot.productionModel.assetVersions||[]).some(v=>v.id===missingVersionId),false);
  assert.equal(await f.repo.getMedia(familyId,missingVersionId),null);
  await assert.rejects(stat(path.join(f.root,second.recipe.output.path)),{code:'ENOENT'});
 };
 await assertAdoptedV1();
 const run2=await f.beginRun(second);
 const busy=await f.workspace(),busyBefore=await f.repo.exportState();
 assert.ok(busy.blockers.some(reason=>reason.includes(run2.runId)));
 assert.equal((await f.materialPost(f.saveBody(busy,'Forbidden retry during submitted run'))).status,409);
 assert.deepEqual(await f.repo.exportState(),busyBefore);
 const unknown=await f.post(f.runs,'v8/runs',{...run2,state:'RESULT_UNKNOWN',note:'Synthetic provider timeout; no real provider was called and no output was created.'});
 assert.equal(unknown.status,201,JSON.stringify(unknown.body));
 const unresolved=await f.workspace(),unknownBefore=await f.repo.exportState();
 assert.ok(unresolved.blockers.some(reason=>reason.includes(run2.runId)));
 assert.equal((await f.materialPost(f.saveBody(unresolved,'Do not retry an unknown result'))).status,409);
 assert.deepEqual(await f.repo.exportState(),unknownBefore);
 await assertNoV2Output();await assertAdoptedV1();
 const failed=await f.post(f.runs,'v8/runs',{...run2,state:'FAILED',note:'Synthetic moderation rejection used solely to test the FAILED/no-output protocol; no provider call occurred.',
  reconciliationEvidence:{requestId:run2.executionRequestId,logId:'synthetic-moderation-rejection-with-no-output',providerStatusCheckedAt:new Date().toISOString(),providerConclusion:'FAILED'}});
 assert.equal(failed.status,201,JSON.stringify(failed.body));
 const remake=await f.workspace();
 assert.equal(remake.mode,'REVISION');assert.deepEqual(remake.blockers,[]);
 assert.equal(remake.parentVersionId,v1.versionId);assert.equal(remake.parentVersionSha256,v1.sha256);
 assert.equal(remake.currentDefinitionId,second.recipe.id);assert.equal(remake.plannedVersionLabel,'V003');
 assert.notEqual(remake.basisHash,unresolved.basisHash,'resolving the unknown attempt changes the exact authoring basis');
 const proof=remake.basis.revision.failedAttempt;
 assert.equal(proof.schemaVersion,'FAILED_OUTPUT_REMAKE_V1');
 assert.equal(proof.definitionId,second.recipe.id);assert.equal(proof.expectedOutputId,second.recipe.output.expectedOutputRef);
 assert.equal(proof.parentDefinitionId,first.recipe.id);assert.equal(proof.parentExpectedOutputId,first.recipe.output.expectedOutputRef);
 assert.equal(proof.parentMedia.versionId,v1.versionId);assert.equal(proof.parentMedia.sha256,v1.sha256);
 assert.deepEqual(proof.absence,{path:second.recipe.output.path,versionId:missingVersionId,candidates:0,registeredMedia:0,fileState:'ABSENT'});
 assert.deepEqual(proof.runs.find(e=>e.eventId===failed.body.event.eventId),failed.body.event,'the exact terminal failure event is frozen, not summarized into a success');
 assert.deepEqual(proof.requests[0].inputBindings,referenceInput?[{order:1,path:first.recipe.output.path,assetFamilyRef:familyId,assetVersionRef:v1.versionId,sha256:v1.sha256}]:[],'failure evidence binds actual five-field execution inputs, not three-field authoring inputs');
 const deniedBefore=await f.repo.exportState();
 assert.equal((await f.materialPost(f.saveBody(remake,'Forbidden stale operational CAS'),{headers:{'If-Match':'"stale-failed-attempt-cas"'}})).status,412);
 assert.equal((await f.materialPost({...f.saveBody(remake,'Forbidden stale failure basis'),expectedBasisHash:unresolved.basisHash})).status,409);
 assert.deepEqual(await f.repo.exportState(),deniedBefore,'stale requests cannot create AUX drafts or new definitions');
 const beforeThird=await f.repo.readView(),history=structuredClone(beforeThird.eventsByKind);
 const frozenSources=await f.repo.readTransaction(async tx=>Promise.all([first.recipe.sourceRevisionId,second.recipe.sourceRevisionId].map(id=>tx.readDocumentRevision(id))));
 const third=await f.provision(remake,'Third fixed local PNG fixture after confirmed failure; no model invocation.',{expectedMode:'REVISION',inputBindings});
 assert.equal(third.result.familyId,familyId);assert.equal(third.result.workItemId,first.result.workItemId);
 assert.equal(third.plan.expectedOutput.plannedVersionLabel,'V003');
 assert.equal(third.recipe.parentVersionId,v1.versionId);assert.equal(third.recipe.parentVersionSha256,v1.sha256);
 assert.equal(third.plan.previousDefinitionId,second.recipe.id);assert.equal(third.plan.previousExpectedOutputId,second.recipe.output.expectedOutputRef);
 assert.deepEqual(third.plan.basis.revision.failedAttempt,proof);
 assert.notEqual(third.recipe.id,second.recipe.id);assert.notEqual(third.recipe.output.expectedOutputRef,second.recipe.output.expectedOutputRef);
 assert.deepEqual((await f.repo.readView()).eventsByKind,history,'authoring a remake cannot modify the failed Run or original ReviewEvent');
 const staleDispatchBefore=await f.repo.exportState();
 const staleDispatch=await f.post(f.runs,'v8/runs',{executionRequestId:run2.executionRequestId,executionDefinitionId:run2.executionDefinitionId,callPackageHash:run2.callPackageHash,state:'SUBMITTED',note:'Forbidden fresh dispatch using an older failed output authorization.'});
 assert.equal(staleDispatch.status,409,JSON.stringify(staleDispatch.body));
 assert.match(JSON.stringify(staleDispatch.body),/snapshot/i);
 assert.deepEqual(await f.repo.exportState(),staleDispatchBefore,'publishing V003 makes the older failed V002 authorization unable to dispatch a new Run');
 await assertNoV2Output();await assertAdoptedV1();
 const run3=await f.beginRun(third),v3=await f.register(third,run3,pngs[1],{wrongParentVersionId:missingVersionId});
 assert.equal(v3.versionId,familyId+'@V003');
 const candidate=(await f.repo.readView()).eventsByKind['asset-version'].find(e=>e.versionId===v3.versionId);
 assert.equal(candidate.parentVersionId,v1.versionId);assert.equal(candidate.parentVersionSha256,v1.sha256);
 assert.equal(candidate.expectedOutputId,third.recipe.output.expectedOutputRef);assert.equal(candidate.executionDefinitionId,third.recipe.id);
 await f.evidence(familyId,v1);await f.evidence(familyId,v3);await assertAdoptedV1();
 await f.review(third,v3,'APPROVE_AND_RELEASE');
 const state=(await f.store.operationalSnapshot()).stateProjection;
 assert.equal(state.assetFamiliesById[familyId].currentVersionId,v3.versionId);
 assert.equal(state.assetVersionsById[v3.versionId].canFlowDownstream,true);
 assert.equal(state.assetVersionsById[missingVersionId],undefined);
 await assertNoV2Output();
 const end=await f.repo.readView();
 for(const old of [first.recipe,second.recipe])assert.deepEqual(end.recipes.executionDefinitions.find(d=>d.id===old.id),old);
 assert.deepEqual(end.snapshot.productionModel.expectedOutputs.find(o=>o.id===second.recipe.output.expectedOutputRef),beforeThird.snapshot.productionModel.expectedOutputs.find(o=>o.id===second.recipe.output.expectedOutputRef));
 for(const [kind,rows] of Object.entries(history))for(const old of rows)assert.deepEqual(end.eventsByKind[kind].find(e=>e.eventId===old.eventId),old);
 for(const source of frozenSources){const after=await f.repo.readTransaction(tx=>tx.readDocumentRevision(source.revisionId));assert.deepEqual(after,source);assert.equal(sha256(after.bytes),source.sha256);}
 assert.equal(sha256(await readFile(path.join(f.root,first.recipe.output.path))),v1.sha256);
 assert.equal(end.snapshot.productionModel.materialProductionPlans.filter(p=>p.familyId===familyId).length,1);
 assert.equal(end.snapshot.productionModel.expectedOutputs.filter(o=>o.familyId===familyId).length,3);
 const documents=await f.repo.readTransaction(async tx=>Promise.all(end.sourceRevisionIds.map(id=>tx.readDocumentRevision(id))));
 const preserved=preserveMaterialProductionProjection({snapshot:end.snapshot,recipes:end.recipes,baseSnapshot:end.snapshot,baseRecipes:end.recipes,documents});
 assert.deepEqual(preserved.recipes.executionDefinitions.filter(d=>d.workItemRef===first.result.workItemId),end.recipes.executionDefinitions.filter(d=>d.workItemRef===first.result.workItemId));
 if(verifyNativeProof)await verifyNativeProof({f,end,state,documents,preserved,v1,v3,missingVersionId,referenceInput});
 assert.deepEqual(legacyObjects(end),legacy);assert.equal(f.externalCalls(),0);
}
